# ruff: noqa
# flake8: noqa
from amsec.notebook.keras_common import *  # noqa: F401,F403
from amsec.notebook.keras_common import keras, np, time, to_categorical  # explicit for readers


class MobileNetV4Model:
    """
    Further enhanced Lightweight Conv + Dense Network
    Aimed at ≥ 99.9% accuracy while remaining relatively compact.
    """

    def __init__(self, input_dim, num_classes=2, use_attention=False):
        self.input_dim = input_dim
        self.num_classes = num_classes
        self.use_attention = use_attention
        self.model = None
        self.history = None
        self.params = 0
        self.flops = 0
        self.training_time = 0
        self.inference_time = 0

    def build_model(self):
        inputs = Input(shape=(self.input_dim,))
        x = BatchNormalization()(inputs)

        x = Reshape((self.input_dim, 1))(x)

        # Stronger Conv blocks
        x = Conv1D(filters=48, kernel_size=3, padding='same',
                   activation='relu', kernel_initializer='he_normal',
                   kernel_regularizer=l2(5e-5))(x)
        x = BatchNormalization()(x)
        x = MaxPooling1D(pool_size=2)(x)
        x = Dropout(0.12)(x)

        x = Conv1D(filters=64, kernel_size=3, padding='same',
                   activation='relu', kernel_initializer='he_normal',
                   kernel_regularizer=l2(5e-5))(x)
        x = BatchNormalization()(x)
        x = MaxPooling1D(pool_size=2)(x)
        x = Dropout(0.12)(x)

        x = Conv1D(filters=96, kernel_size=3, padding='same',
                   activation='relu', kernel_initializer='he_normal',
                   kernel_regularizer=l2(5e-5))(x)
        x = BatchNormalization()(x)

        avg_pool = GlobalAveragePooling1D()(x)
        max_pool = GlobalMaxPooling1D()(x)
        x = Concatenate()([avg_pool, max_pool])
        x = Dropout(0.2)(x)

        # Larger dense tower
        x = Dense(128, activation='relu',
                  kernel_regularizer=l2(5e-5),
                  kernel_initializer='he_normal')(x)
        x = BatchNormalization()(x)
        x = Dropout(0.25)(x)

        x = Dense(64, activation='relu',
                  kernel_regularizer=l2(5e-5),
                  kernel_initializer='he_normal')(x)
        x = BatchNormalization()(x)
        x = Dropout(0.2)(x)

        if self.use_attention:
            attn_input = Reshape((1, 64))(x)
            attn_out = MultiHeadAttention(num_heads=4, key_dim=16, dropout=0.1)(attn_input, attn_input)
            attn_out = Flatten()(attn_out)
            attn_out = LayerNormalization()(attn_out)
            x = Concatenate()([x, attn_out])

            x = Dense(64, activation='relu',
                      kernel_regularizer=l2(5e-5),
                      kernel_initializer='he_normal')(x)
            x = BatchNormalization()(x)
            x = Dropout(0.15)(x)

        outputs = Dense(self.num_classes, activation='softmax')(x)

        self.model = Model(inputs, outputs)
        self.params = self.model.count_params()
        self.flops = get_model_flops(self.model)

        model_name = "MobileNetV4+Attention" if self.use_attention else "MobileNetV4"
        print(f"  {model_name} Parameters: {self.params:,}")
        print(f"  {model_name} FLOPs: {self.flops:,}")

        return self.model

    def train(self, X_train, y_train, X_val, y_val, epochs=30, batch_size=128):
        y_train_cat = to_categorical(y_train, num_classes=self.num_classes)
        y_val_cat = to_categorical(y_val, num_classes=self.num_classes)

        class_counts = np.bincount(y_train.astype(int))
        total = len(y_train)
        class_weight = {i: total / (len(class_counts) * max(c, 1)) for i, c in enumerate(class_counts)}

        self.model.compile(
            optimizer=AdamW(learning_rate=1.2e-3, weight_decay=5e-5, clipnorm=1.0),
            loss='categorical_crossentropy',
            metrics=['accuracy', keras.metrics.AUC(name='auc')]
        )

        callbacks = [
            EarlyStopping(monitor='val_loss', patience=12, restore_best_weights=True, verbose=1),
            ReduceLROnPlateau(monitor='val_loss', factor=0.5, patience=4, min_lr=1e-7, verbose=1)
        ]

        start_time = time.time()
        self.history = self.model.fit(
            X_train, y_train_cat,
            validation_data=(X_val, y_val_cat),
            epochs=epochs,
            batch_size=batch_size,
            callbacks=callbacks,
            class_weight=class_weight,
            verbose=1
        )
        self.training_time = time.time() - start_time
        print(f"\n✓ Training completed in {self.training_time:.2f} seconds")
        return self.history

    def evaluate(self, X_test, y_test):
        start_time = time.time()
        y_test_pred_proba = self.model.predict(X_test, verbose=0)
        self.inference_time = time.time() - start_time

        y_test_pred = np.argmax(y_test_pred_proba, axis=1)

        accuracy = accuracy_score(y_test, y_test_pred)
        precision = precision_score(y_test, y_test_pred, average='weighted', zero_division=0)
        recall = recall_score(y_test, y_test_pred, average='weighted', zero_division=0)
        f1 = f1_score(y_test, y_test_pred, average='weighted', zero_division=0)
        mcc = matthews_corrcoef(y_test, y_test_pred)
        balanced_acc = balanced_accuracy_score(y_test, y_test_pred)

        y_test_binarized = to_categorical(y_test, num_classes=self.num_classes)
        roc_auc = roc_auc_score(y_test_binarized, y_test_pred_proba, multi_class='ovr', average='weighted')

        return {
            'accuracy': accuracy,
            'precision': precision,
            'recall': recall,
            'f1_score': f1,
            'mcc': mcc,
            'balanced_accuracy': balanced_acc,
            'roc_auc': roc_auc,
            'confusion_matrix': confusion_matrix(y_test, y_test_pred),
            'predictions': y_test_pred,
            'probabilities': y_test_pred_proba,
            'history': self.history,
            'training_time': self.training_time,
            'inference_time': self.inference_time,
            'n_params': self.params,
            'flops': self.flops
        }
